-- ==============================================================================
-- CityTwin AI — Migration 002: Seed Data for Chandigarh Union Territory
-- Contains authoritative data for 64 sectors, 11 hospitals, 6 candidate sites
-- and dataset registry entries.
-- ==============================================================================

BEGIN;

-- 1. Seed Dataset Registry
ON CONFLICT (dataset_key) DO NOTHING;

-- 2. Seed Sectors (64 sectors)
ON CONFLICT (sector_name) DO UPDATE SET population = EXCLUDED.population, density_per_sqkm = EXCLUDED.density_per_sqkm;

-- 3. Seed Existing Hospitals (11 facilities)
ON CONFLICT (id) DO UPDATE SET beds = EXCLUDED.beds, daily_opd = EXCLUDED.daily_opd;

-- 4. Seed Candidate Hospital Sites (6 parcels)
ON CONFLICT (id) DO UPDATE SET suitability_score = EXCLUDED.suitability_score, rank = EXCLUDED.rank;

COMMIT;
