INSERT INTO candidate_sites (id, name, sector, description, vacant_land_acres, population_within_2km, distance_to_nearest_hospital_km, road_access, transit_access_score, road_connectivity_score, land_availability_score, healthcare_gap_score, population_demand_score, suitability_score, rank, recommended_type, estimated_cost_cr, rationale, location) VALUES
('cand-site-1', 'Site Alpha: Sector 52 / Maloya Growth Junction', 'Sector 52', 'Zoned Public / Semi-Public Institutional Reserve. Direct access via Vikas Marg & PR-7 Expressway link', 8.4, 142000, 4.6, 'Direct access via Vikas Marg & PR-7 Expressway link', 0.88, 0.92, 0.56, 0.92, 0.947, 86.8, 1, '300-Bed Secondary General Hospital + Trauma Stabilization Unit', 240, 'Extreme population density in Sector 52/Maloya (>40,000/sqkm) with zero tertiary healthcare within 4.5km; relieves severe outpatient backlog at GMCH 32.', ST_SetSRID(ST_MakePoint(76.7215, 30.7095), 4326)),
('cand-site-2', 'Site Beta: Sarangpur Institutional Healthcare Parcel', 'Sarangpur', 'Zoned Institutional Healthcare & Research Reserve. Four-lane corridor connecting to Mullanpur / New Chandigarh', 14.2, 98000, 3.8, 'Four-lane corridor connecting to Mullanpur / New Chandigarh', 0.78, 0.85, 0.947, 0.76, 0.653, 77.2, 2, '400-Bed Tertiary Specialty / AYUSH Super-Specialty Hub', 350, 'High vacant land availability for medical campus expansion; strategically intercepts patient influx from New Chandigarh / Punjab before overwhelming PGIMER.', ST_SetSRID(ST_MakePoint(76.751, 30.771), 4326)),
('cand-site-4', 'Site Delta: Sector 48 / South Corridor Hub', 'Sector 48', 'Zoned Institutional Health Reserve. Dual arterial link connecting Dakshin Marg to Airport Expressway', 6.5, 115000, 3.9, 'Dual arterial link connecting Dakshin Marg to Airport Expressway', 0.8, 0.9, 0.433, 0.78, 0.767, 74.5, 3, '150-Bed Emergency & Trauma Satellite Center', 140, 'Addresses rapid southward demographic expansion into Sectors 48-51; provides high-speed emergency response for southern expressways.', ST_SetSRID(ST_MakePoint(76.759, 30.687), 4326)),
('cand-site-3', 'Site Gamma: Sector 56 / Palsora Transit Boundary', 'Sector 56', 'Zoned Municipal Civic Amenity Parcel. Frontage on Dakshin Marg extension', 5.8, 128000, 3.4, 'Frontage on Dakshin Marg extension', 0.84, 0.89, 0.387, 0.68, 0.853, 74.3, 4, '200-Bed Mother and Child Civil Hospital', 160, 'Serves dense demographic pockets of Sector 56 and Palsora; reduces ambulance travel time to GMSH 16 from 28 mins to 6 mins.', ST_SetSRID(ST_MakePoint(76.702, 30.7285), 4326)),
('cand-site-5', 'Site Epsilon: Manimajra / Modern Housing East Hub', 'Manimajra', 'Zoned Urban Redevelopment & Public Health. Old Panchkula Road & Railway bypass', 4.5, 135000, 2.9, 'Old Panchkula Road & Railway bypass', 0.86, 0.78, 0.3, 0.58, 0.9, 70.6, 5, '120-Bed Sub-Divisional Secondary Expansion', 115, 'Existing Civil Hospital Manimajra is operating at 160% capacity; second facility decongests eastern sub-city.', ST_SetSRID(ST_MakePoint(76.849, 30.731), 4326)),
('cand-site-6', 'Site Zeta: Industrial Area Phase 2 Logistics Boundary', 'Industrial Area Phase 2', 'Zoned Converted Mixed Commercial / Public Facility. Industrial bypass road connecting to Purv Marg', 7.2, 89000, 2.7, 'Industrial bypass road connecting to Purv Marg', 0.75, 0.82, 0.48, 0.54, 0.593, 62.0, 6, '100-Bed Occupational Health & General Ward', 95, 'High industrial workforce concentration with occupational injury risks; lower residential density gives lower comparative priority.', ST_SetSRID(ST_MakePoint(76.799, 30.697), 4326))
